import { useState } from "react";
import {
  ArrowRight,
  CheckCircle,
  Copy,
  Lightbulb,
  ListChecks,
  Sparkles,
  ChevronDown,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import type { Project } from "@/lib/types";

const steps = [
  { number: 1, icon: Lightbulb, label: "Capture idea", status: "idea" },
  { number: 2, icon: Sparkles, label: "Clarify scope", status: "questions" },
  { number: 3, icon: ListChecks, label: "Generate spec", status: "spec" },
  { number: 4, icon: ListChecks, label: "Technical plan", status: "technical-plan" },
  { number: 5, icon: CheckCircle, label: "Agent prompts", status: "export" },
  { number: 6, icon: ListChecks, label: "Review & confirm", status: "review" },
];

interface WizardFlowProps {
  project: Project;
  currentPhase: Project["phase"];
  onProceed: (phase: Project["phase"]) => void;
}

function StepIndicator({ step, currentNumber }: { step: typeof steps[0]; currentNumber: number }) {
  const Icon = step.icon;
  const isCompleted = step.number < currentNumber;
  const isCurrent = step.number === currentNumber;

  return (
    <div className="flex gap-3 items-start">
      <div
        className={`flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center font-semibold transition-all ${
          isCompleted
            ? "bg-emerald-100 text-emerald-700"
            : isCurrent
              ? "bg-blue-100 text-blue-700 ring-2 ring-blue-400"
              : "bg-zinc-100 text-zinc-400"
        }`}
      >
        {isCompleted ? <CheckCircle className="w-5 h-5" /> : step.number}
      </div>
      <div className="pt-1">
        <p
          className={`text-sm font-semibold ${
            isCurrent ? "text-zinc-900" : isCompleted ? "text-emerald-700" : "text-zinc-500"
          }`}
        >
          {step.label}
        </p>
      </div>
    </div>
  );
}

function CopyablePrompt({ text, index }: { text: string; index: number }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="rounded-lg border border-zinc-200 bg-white p-4 hover:shadow-md transition">
      <div className="flex items-start justify-between gap-3 mb-3">
        <Badge tone="blue">Agent {index}</Badge>
        <button
          onClick={handleCopy}
          className="inline-flex items-center gap-2 px-3 py-1.5 text-xs font-medium rounded-md bg-zinc-100 text-zinc-700 hover:bg-zinc-200 transition"
        >
          <Copy className="w-3.5 h-3.5" />
          {copied ? "Copied!" : "Copy"}
        </button>
      </div>
      <p className="text-sm leading-6 text-zinc-700">{text}</p>
    </div>
  );
}

function ChecklistItem({ text, checked = false }: { text: string; checked?: boolean }) {
  return (
    <li className="flex gap-3 text-sm leading-6 text-zinc-700">
      <span className={`flex-shrink-0 w-5 h-5 rounded-full flex items-center justify-center text-xs font-semibold ${checked ? "bg-emerald-100 text-emerald-700" : "bg-zinc-100 text-zinc-400"}`}>
        {checked ? "✓" : "○"}
      </span>
      <span>{text}</span>
    </li>
  );
}

export function WizardFlow({ project, currentPhase, onProceed }: WizardFlowProps) {
  const currentStepNumber = steps.findIndex((s) => s.status === currentPhase) + 1;

  return (
    <div className="space-y-8">
      {/* Step Indicators */}
      <div className="sticky top-20 bg-white/95 backdrop-blur-sm border-b border-zinc-200 -mx-6 px-6 py-6 space-y-4">
        <div className="flex items-center gap-2 mb-4">
          <Sparkles className="w-5 h-5 text-blue-600" />
          <h2 className="text-lg font-semibold text-zinc-900">Building your project</h2>
        </div>
        <div className="grid gap-4 grid-cols-2 sm:grid-cols-3 lg:grid-cols-6">
          {steps.map((step) => (
            <StepIndicator key={step.status} step={step} currentNumber={currentStepNumber} />
          ))}
        </div>
      </div>

      {/* Step Content */}
      <div className="space-y-8">
        {/* Idea Capture */}
        {currentPhase === "idea" && (
          <section className="space-y-4">
            <div>
              <h3 className="text-2xl font-bold text-zinc-900 mb-2">Great idea.</h3>
              <p className="text-zinc-600">
                <strong>"{project.idea}"</strong>
              </p>
              <p className="text-sm text-zinc-500 mt-2">Project: {project.name}</p>
            </div>
            <Button onClick={() => onProceed("questions")} className="flex items-center gap-2">
              Next: Clarify scope
              <ArrowRight className="w-4 h-4" />
            </Button>
          </section>
        )}

        {/* Clarifying Questions */}
        {currentPhase === "questions" && (
          <section className="space-y-6">
            <div>
              <h3 className="text-2xl font-bold text-zinc-900 mb-1">Clarifying questions</h3>
              <p className="text-zinc-600">
                Answer these to sharpen your vision before we generate the spec.
              </p>
            </div>
            <div className="rounded-lg border border-zinc-200 bg-white p-6 space-y-4">
              <ul className="space-y-4">
                {project.clarifyingQuestions.map((question, idx) => (
                  <ChecklistItem key={idx} text={question} checked={false} />
                ))}
              </ul>
            </div>
            <div className="flex gap-3">
              <Button
                onClick={() => onProceed("idea")}
                variant="secondary"
              >
                Back
              </Button>
              <Button onClick={() => onProceed("spec")} className="flex items-center gap-2">
                Generate spec
                <ArrowRight className="w-4 h-4" />
              </Button>
            </div>
          </section>
        )}

        {/* App Spec */}
        {currentPhase === "spec" && (
          <section className="space-y-6">
            <div>
              <h3 className="text-2xl font-bold text-zinc-900 mb-1">Generated app spec</h3>
              <p className="text-zinc-600">
                This is your structured specification. Review and adjust if needed.
              </p>
            </div>
            <div className="rounded-lg border border-zinc-200 bg-white p-6 space-y-6">
              <div>
                <h4 className="font-semibold text-zinc-900 mb-2">Target Audience</h4>
                <p className="text-sm text-zinc-700">{project.appSpec.audience}</p>
              </div>
              <div>
                <h4 className="font-semibold text-zinc-900 mb-2">Problem to Solve</h4>
                <p className="text-sm text-zinc-700">{project.appSpec.problem}</p>
              </div>
              <div>
                <h4 className="font-semibold text-zinc-900 mb-3">Core Features</h4>
                <ul className="space-y-2">
                  {project.appSpec.coreFeatures.map((feature, idx) => (
                    <ChecklistItem key={idx} text={feature} checked={true} />
                  ))}
                </ul>
              </div>
              <div>
                <h4 className="font-semibold text-zinc-900 mb-3">Non-Goals</h4>
                <ul className="space-y-2">
                  {project.appSpec.nonGoals.map((goal, idx) => (
                    <li key={idx} className="flex gap-3 text-sm text-zinc-700">
                      <span className="text-zinc-400">✕</span>
                      <span>{goal}</span>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
            <div className="flex gap-3">
              <Button
                onClick={() => onProceed("questions")}
                variant="secondary"
              >
                Back
              </Button>
              <Button onClick={() => onProceed("technical-plan")} className="flex items-center gap-2">
                Next: Technical plan
                <ArrowRight className="w-4 h-4" />
              </Button>
            </div>
          </section>
        )}

        {/* Technical Plan */}
        {currentPhase === "technical-plan" && (
          <section className="space-y-6">
            <div>
              <h3 className="text-2xl font-bold text-zinc-900 mb-1">Technical implementation plan</h3>
              <p className="text-zinc-600">
                Here's how to build this. Adjust as needed before moving to agent prompts.
              </p>
            </div>
            <div className="space-y-4">
              <div className="rounded-lg border border-zinc-200 bg-white p-6">
                <h4 className="font-semibold text-zinc-900 mb-3">Build sequence</h4>
                <ol className="space-y-2">
                  {project.technicalPlan.map((item, idx) => (
                    <li key={idx} className="flex gap-3 text-sm text-zinc-700">
                      <span className="flex-shrink-0 font-semibold text-zinc-500 w-6">{idx + 1}.</span>
                      <span>{item}</span>
                    </li>
                  ))}
                </ol>
              </div>
              <div className="rounded-lg border border-zinc-200 bg-white p-6">
                <h4 className="font-semibold text-zinc-900 mb-3">Scaffold strategy</h4>
                <ol className="space-y-2">
                  {project.scaffoldPlan.map((item, idx) => (
                    <li key={idx} className="flex gap-3 text-sm text-zinc-700">
                      <span className="flex-shrink-0 font-semibold text-zinc-500 w-6">{idx + 1}.</span>
                      <span>{item}</span>
                    </li>
                  ))}
                </ol>
              </div>
            </div>
            <div className="flex gap-3">
              <Button
                onClick={() => onProceed("spec")}
                variant="secondary"
              >
                Back
              </Button>
              <Button onClick={() => onProceed("export")} className="flex items-center gap-2">
                Next: Agent prompts
                <ArrowRight className="w-4 h-4" />
              </Button>
            </div>
          </section>
        )}

        {/* Export Prompts */}
        {currentPhase === "export" && (
          <section className="space-y-6">
            <div>
              <h3 className="text-2xl font-bold text-zinc-900 mb-1">Four agent prompts</h3>
              <p className="text-zinc-600">
                These prompts are ready to copy and paste into your agent workspace.
              </p>
            </div>
            <div className="grid gap-4 sm:grid-cols-2">
              {project.exportPrompts.map((prompt, idx) => (
                <CopyablePrompt key={idx} text={prompt} index={idx + 1} />
              ))}
